import collections
import random
import time

class StorageNode:
    def __init__(self, node_id):
        self.node_id = node_id
        self.data = {}
        self.access_logs = collections.defaultdict(list)

    def put(self, key, value):
        self.data[key] = value

    def get(self, key):
        if key in self.data:
            self.access_logs[key].append(time.time())
            return self.data[key]
        return None

    def remove(self, key):
        return self.data.pop(key, None)

class PredictiveOrchestrator:
    def __init__(self, nodes):
        self.nodes = nodes
        self.access_patterns = collections.defaultdict(list)

    def record_telemetry(self):
        for node in self.nodes:
            for key, timestamps in node.access_logs.items():
                self.access_patterns[key].extend(timestamps)
                node.access_logs[key] = []

    def predict_next_node(self, key):
        # Simulated AI logic: Predicts movement based on access frequency
        # In a full system, this would use a LSTM or Transformer model
        return random.choice(self.nodes)

    def rebalance(self):
        self.record_telemetry()
        for key in list(self.access_patterns.keys()):
            target_node = self.predict_next_node(key)

            # Move data to the predicted node
            for node in self.nodes:
                if key in node.data:
                    val = node.remove(key)
                    target_node.put(key, val)
                    break

class DistributedKVStore:
