import collections

class BasicBPETokenizer:
    def __init__(self, vocab_size=300):
        self.vocab_size = vocab_size
        self.vocab = {}
        self.merges = {}

    def _get_stats(self, ids):
        counts = collections.defaultdict(int)
        for i in range(len(ids) - 1):
            counts[(ids[i], ids[i+1])] += 1
        return counts

    def _merge(self, ids, pair, idx):
        new_ids = []
        i = 0
        while i < len(ids):
            if i < len(ids) - 1 and ids[i] == pair[0] and ids[i+1] == pair[1]:
                new_ids.append(idx)
                i += 2
            else:
                new_ids.append(ids[i])
                i += 1
        return new_ids

    def train(self, text):
        # Initial vocabulary based on characters
        tokens = list(text)
        unique_chars = sorted(list(set(tokens)))
        self.vocab = {char: i for i, char in enumerate(unique_chars)}

        ids = [self.vocab[char] for char in tokens]

        num_merges = self.vocab_size - len(self.vocab)
        for i in range(num_merges):
            stats = self._get_stats(ids)
            if not stats:
                break

            best_pair = max(stats, key=stats.get)
            new_id = len(self.vocab)
            self.merges[best_pair] = new_id
            self.vocab[chr(new_id)] = new_id # Simplified mapping
            ids = self._merge(ids, best_pair, new_id)

    def tokenize(self, text):
        ids = [self.vocab.get(char, 0) for char in list(text)]

        # Apply learned merges in order
        for pair, new_id in self.merges.items():
            ids = self._merge(ids, pair, new_id)

        return ids

# Example usage for a sample string
