### Architectural Framework for Micro-Price Prediction

A production-grade HFT system typically separates concerns into three primary layers: the Market Data Handler, the Strategy Engine (where the RL agent resides), and the Order Gateway.

```cpp
#include <iostream>
#include <vector>
#include <map>
#include <algorithm>
#include <cmath>
#include <random>

// Represents the state of the Limit Order Book (LOB)
struct MarketState {
    double mid_price;
    double bid_ask_spread;
    double order_book_imbalance;
    int volatility_bucket;

    // Simple hash for state representation in a Q-table
    bool operator<(const MarketState& other) const {
        return std::tie(mid_price, bid_ask_spread, order_book_imbalance, volatility_bucket) <
               std::tie(other.mid_price, other.bid_ask_spread, other.order_book_imbalance, other.volatility_bucket);
    }
};

enum Action { BUY, SELL, HOLD };

class MicroPriceRLAgent {
private:
    std::map<MarketState, std::vector<double>> q_table;
    double learning_rate;
    double discount_factor;
    double epsilon;

public:
    MicroPriceRLAgent(double lr = 0.1, double df = 0.95, double eps = 0.1)
        : learning_rate(lr), discount_factor(df), epsilon(eps) {}

    Action select_action(const MarketState& state) {
        // Epsilon-greedy exploration
        std::default_random_engine generator;
        std::uniform_real_distribution<double> distribution(0.0, 1.0);

        if (distribution(generator) < epsilon) {
            return static_cast<Action>(std::rand() % 3);
        }

        if (q_table.find(state) == q_table.end()) {
            q_table[state] = {0.0, 0.0, 0.0};
            return HOLD;
        }

        auto& actions = q_table[state];
        auto it = std::max_element(actions.begin(), actions.end());
        return static_cast<Action>(std::distance(actions.begin(), it));
    }

    void update(const MarketState& state, Action action, double reward, const MarketState& next_state) {
        if (q_table.find(state) == q_table.end()) q_table[state] = {0.0, 0.0, 0.0};
        if (q_table.find(next_state) == q_table.end()) q_table[next_state] = {0.0, 0.0, 0.0};

        double max_next_q = *std::max_element(q_table[next_state].begin(), q_table[next_state].end());

        // Bellman Equation update
        q_table[state][action] += learning_rate * (reward + discount_factor * max_next_q - q_table[state][action]);
    }
};

int main() {
    MicroPriceRLAgent agent;

    // Mock Market State: Imbalance, Spread, Volatility
    MarketState current_state = {150.25, 0.01, 0.65, 2};

    Action action = agent.select_action(current_state);
    std::cout << "Agent selected action: " << action << std::endl;

    // Mock reward based on price movement
    double reward = (action == BUY) ? 1.0 : -1.0; 
    MarketState next_state = {150.26, 0.01, 0.70, 2};

    agent.update(current_state, action, reward, next_state);

    return 0;
}
