```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ComputeRewardDistributor
 * @dev Handles the tracking and claiming of rewards for GPU compute nodes.
 */
contract ComputeRewardDistributor {
    address public owner;

    // Mapping of node addresses to their accumulated rewards in wei
    mapping(address => uint256) public pendingRewards;

    event RewardDistributed(address indexed node, uint256 amount);
    event RewardClaimed(address indexed node, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Caller is not the owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    /**
     * @dev Updates the reward balance for a specific node.
     * In a production environment, this would be called by a verified 
     * off-chain oracle or a consensus layer.
     */
    function distributeRewards(address[] calldata nodes, uint256[] calldata amounts) external onlyOwner {
        require(nodes.length == amounts.length, "Array length mismatch");

        for (uint256 i = 0; i < nodes.length; i++) {
            pendingRewards[nodes[i]] += amounts[i];
            emit RewardDistributed(nodes[i], amounts[i]);
        }
    }

    /**
     * @dev Allows nodes to withdraw their accumulated rewards.
     */
    function claimRewards() external {
        uint256 amount = pendingRewards[msg.sender];
        require(amount > 0, "No rewards to claim");

        pendingRewards[msg.sender] = 0;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        require(success, "Transfer failed");

        emit RewardClaimed(msg.sender, amount);
    }

    /**
     * @dev Allows the owner to fund the contract.
     */
    receive() external payable {}

    function withdrawAdminFunds() external onlyOwner {
        payable(owner).transfer(address(this).balance);
    }
}
